import{_ as d,a0 as l,w as s,s as i,ao as p,I as r,x as o,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"安裝 Fedora 22 後要做的事情 | LCTT x X-CMD","titleTemplate":false,"description":"安裝 Fedora 22 後要做的事情 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝 Fedora 22 後要做的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝 Fedora 22 後要做的事情 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150528 Things To Do After Installing Fedora 22","title":"安裝 Fedora 22 後要做的事情","tag":"201506","desc":""},"relativePath":"201506/20150528 Things To Do After Installing Fedora 22.md","filePath":"[post].md"}'),m={name:"201506/20150528 Things To Do After Installing Fedora 22.md"};function g(h,e,u,f,c,b){const a=l("Link");return s(),i("div",null,[e[19]||(e[19]=p(`<h1 id="安裝-fedora-22-後要做的事情" tabindex="-1">安裝 Fedora 22 後要做的事情 <a class="header-anchor" href="#安裝-fedora-22-後要做的事情" aria-label="Permalink to “安裝 Fedora 22 後要做的事情”">​</a></h1><p>Red Hat操作系統的社區開發版的最新成員Fedora 22，已經於2015年5月26日發佈了。對這個經典的Fedora發行版的發佈充斥着各種猜測和預期，而最終Fedora 22推出了許多重大變化。</p><p>就初始化進程而言，Systemd還是個新生兒，但它已經準備好替換古老的sysvinit這個一直是Linux生態系統一部分的模組。另外一個用户會碰到的重大改變存在於基本倉庫的python版本中，這裏提供了兩種不同口味的python版本，2.x和3.x分支，各個都有其不同的偏好和優點。所以，那些偏好2.x口味的用户可能想要安裝他們喜愛的python版本。自從Fedora 18開始 dandified YUM安裝器（即 DNF）就準備替換過時陳舊的YUM安裝器了，Fedora最後決定，現在就用DNF來替換YUM。</p><h3 id="_1-配置rpmfusion倉庫" tabindex="-1">1) 配置RPMFusion倉庫 <a class="header-anchor" href="#_1-配置rpmfusion倉庫" aria-label="Permalink to “1) 配置RPMFusion倉庫”">​</a></h3><p>正如我已經提到過的，Fedora的意識形態很是嚴謹，它不會自帶任何非自由組件。官方倉庫不會提供一些包含有非自由組件的基本軟件，比如像多媒體編碼。因此，安裝一些第三方倉庫很有必要，這些倉庫會為我們提供一些基本的軟件。幸運的是，RPMFusion倉庫前來拯救我們了。</p><pre><code>$ sudo dnf install --nogpgcheck http://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-22.noarch.rpm
</code></pre><h3 id="_2-安裝vlc媒體播放器" tabindex="-1">2) 安裝VLC媒體播放器 <a class="header-anchor" href="#_2-安裝vlc媒體播放器" aria-label="Permalink to “2) 安裝VLC媒體播放器”">​</a></h3><p>Fedora 22默認自帶了媒體播放器，即 gnome視頻播放器（以前叫做totem）。如果你覺得還好，那麼我們可以跳過這一步繼續往前走。但是，如果你像我一樣，偏好使用最廣泛的VLC，那麼就去從RPMFusion倉庫安裝吧。安裝方法如下：</p><pre><code>sudo dnf install vlc -y
</code></pre><h3 id="_3-安裝多媒體編碼" tabindex="-1">3) 安裝多媒體編碼 <a class="header-anchor" href="#_3-安裝多媒體編碼" aria-label="Permalink to “3) 安裝多媒體編碼”">​</a></h3><p>剛剛我們説過，一些多媒體編碼和插件不會隨Fedora一起發送。現在，有誰想僅僅是因為專有編碼而錯過他們最愛的節目和電影？試試這個吧：</p><pre><code>$ sudo dnf install gstreamer-plugins-bad gstreamer-plugins-bad-free-extras gstreamer-plugins-ugly gstreamer-ffmpeg gstreamer1-libav gstreamer1-plugins-bad-free-extras gstreamer1-plugins-bad-freeworld gstreamer-plugins-base-tools gstreamer1-plugins-good-extras gstreamer1-plugins-ugly gstreamer1-plugins-bad-free gstreamer1-plugins-good gstreamer1-plugins-base gstreamer1
</code></pre><h3 id="_4-更新系統" tabindex="-1">4) 更新系統 <a class="header-anchor" href="#_4-更新系統" aria-label="Permalink to “4) 更新系統”">​</a></h3><p>Fedora是一個前鋭的發行版，因此它會不斷髮布更新用以修復系統中出現的錯誤和漏洞。因而，保持系統更新到最新，是個不錯的做法。</p><pre><code>$ sudo dnf update -y
</code></pre><h3 id="_5-卸載你不需要的軟件" tabindex="-1">5) 卸載你不需要的軟件 <a class="header-anchor" href="#_5-卸載你不需要的軟件" aria-label="Permalink to “5) 卸載你不需要的軟件”">​</a></h3><p>Fedora預裝了一些大多數用户都有用的軟件包，但是對於更高級的用户，你可能知道到你並不需要它。要移除你不需要的包相當容易，只需使用以下命令——我選擇卸載rhythmbox，因為我知道我不會用到它：</p><pre><code>$ sudo dnf remove rhythmbox
</code></pre><h3 id="_6-安裝adobe-flash" tabindex="-1">6) 安裝Adobe Flash <a class="header-anchor" href="#_6-安裝adobe-flash" aria-label="Permalink to “6) 安裝Adobe Flash”">​</a></h3><p>我們都希望Adobe Flash不要再存在了，因為它並不被認為是最安全的，或者存在資源問題，但是暫時先讓它待着吧。Fedora 22安裝Adobe Flash的唯一途徑是從Adobe安裝官方RPM，就像下面這樣。</p>`,20)),r("p",null,[e[1]||(e[1]=o("你可以從",-1)),t(a,{href:"https://get.adobe.com/flashplayer/"},{default:n(()=>[...e[0]||(e[0]=[o("這裏",-1)])]),_:1}),e[2]||(e[2]=o("下載RPM。下載完後，你可以直接右擊並像下面這樣打開：",-1))]),e[20]||(e[20]=r("p",null,[r("img",{src:"http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-27-at-9.50.42-PM.png",alt:"Install Adobe Flash"})],-1)),e[21]||(e[21]=r("p",null,"右擊並選擇“用軟件安裝打開”",-1)),e[22]||(e[22]=r("p",null,"然後，只需在彈出窗口中點擊安裝：",-1)),e[23]||(e[23]=r("p",null,[r("img",{src:"http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-27-at-9.51.07-PM.png",alt:"Install Adobe"})],-1)),e[24]||(e[24]=r("p",null,[r("em",null,"點擊“安裝”來完成安裝Adobe定製RPM的過程")],-1)),e[25]||(e[25]=r("p",null,"該過程完成後，“安裝”按鈕會變成“移除”，而此時安裝也完成了。如果在此過程中你的瀏覽器開着，會提示你先把它關掉或在安裝完成後重啓以使修改生效。",-1)),e[26]||(e[26]=r("h3",{id:"_7-用gnome-boxes加速虛擬機",tabindex:"-1"},[o("7) 用Gnome Boxes加速虛擬機 "),r("a",{class:"header-anchor",href:"#_7-用gnome-boxes加速虛擬機","aria-label":"Permalink to “7) 用Gnome Boxes加速虛擬機”"},"​")],-1)),r("p",null,[e[4]||(e[4]=o("你剛剛安裝了Fedora，你也很是喜歡，但是出於某些私人原因，你也許仍然需要Windows，或者你只是想玩玩另外一個Linux發行版。不管哪種情況，你都可以使用Gnome Boxes來簡單地創建一個虛擬機或使用一個live發行版，Fedora 22提供了該軟件。遵循以下步驟，使用你所選的ISO來開始吧！誰知道呢，也許你可以檢驗一下某個",-1)),t(a,{href:"http://spins.fedoraproject.org/"},{default:n(()=>[...e[3]||(e[3]=[o("Fedora Spin",-1)])]),_:1}),e[5]||(e[5]=o("。",-1))]),e[27]||(e[27]=p(`<p>首先，打開Gnome Boxes，然後在頂部左邊選擇“新建”：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-27-at-10.24.46-PM.png" alt="Add a new virtual machine (box)"></p><p>點擊“新建”來開始添加一個新虛擬機的進程吧。</p><p>接下來，點擊打開文件並選擇一個ISO：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-27-at-10.28.44-PM.png" alt="Choose ISO"></p><p><em>在點擊了“選擇文件或ISO”後，選擇你的ISO。這裏，我已經安裝了一個Debian ISO。</em></p><p>最後，自定義VM設置或使用默認配置，然後點擊“創建”。VM默認會啓動，可用的VM會在Gnome Boxes以小縮略圖的方式顯示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-27-at-10.31.11-PM.png" alt="Create VM"></p><p><em>自定義你自己的設置，或者也可以保持默認。完成後，點擊“創建”，VM就一切就緒了。</em></p><h3 id="_8-添加社交媒體和其它在線帳號" tabindex="-1">8) 添加社交媒體和其它在線帳號 <a class="header-anchor" href="#_8-添加社交媒體和其它在線帳號" aria-label="Permalink to “8) 添加社交媒體和其它在線帳號”">​</a></h3><p>Gnome自帶有不錯的內建功能用於容納帳號相關的東西，像Facebook，Google以及其它在線帳號。你可以通過Gnome設置應用訪問在線帳號設置，可以在桌面上右鍵點擊或在應用程序中找到該應用。然後，只需點擊在線帳號，並添加你所選擇的帳號。如果你要添加一個帳號，比如像Google，你可以用它來作為默認帳號，用來完成諸如發送郵件、日曆提醒、相片和文檔交互，以及諸如此類的更多事情。</p><h3 id="_9-安裝kde或另一個桌面環境" tabindex="-1">9) 安裝KDE或另一個桌面環境 <a class="header-anchor" href="#_9-安裝kde或另一個桌面環境" aria-label="Permalink to “9) 安裝KDE或另一個桌面環境”">​</a></h3><p>我們中的某些人不喜歡Gnome，那也沒問題。在終端中運行以下命令來安裝KDE所需的一切來替換它。這些指令也可以用以安裝xfce、lxde或其它桌面環境。</p><pre><code>$ sudo dnf install @kde-desktop
</code></pre><p>安裝完成後，登出。當你點擊你的用户名時，注意那個表示設置的小齒輪。點擊它，然後選擇“Plasma”。當你再次登錄時，一個全新的KDE桌面就會歡迎你。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-27-at-11.32.27-PM.png" alt="Plasma on Fedora 22"></p><p><em>剛剛安裝到Fedora 22上的Plasma環境</em></p><p>####在 Fedora 22中安裝 Cinnamon桌面：####</p><p>打開SSH終端，輸入或粘帖如下命令並回車：</p><pre><code>sudo dnf install @cinnamon-desktop
</code></pre><p>####在 Fedora 22中安裝 MATE桌面：####</p><p>打開SSH終端，輸入或粘帖如下命令並回車：</p><pre><code>sudo dnf install @mate-desktop
</code></pre><p>####在 Fedora 22中安裝 XFCE桌面：####</p><p>打開SSH終端，輸入或粘帖如下命令並回車：</p><pre><code>sudo dnf install @xfce-desktop
</code></pre><p>####在 Fedora 22中安裝 LXDE桌面：####</p><p>打開SSH終端，輸入或粘帖如下命令並回車：</p><pre><code>sudo dnf install @lxde-desktop
</code></pre><h3 id="_10-定製桌面並優化設置" tabindex="-1">10) 定製桌面並優化設置 <a class="header-anchor" href="#_10-定製桌面並優化設置" aria-label="Permalink to “10) 定製桌面並優化設置”">​</a></h3><p>默認的 Gnome 帶有一張黑色背景和一個新的鎖屏，幸運的是，很容易通過下面的方式來改變：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-28-at-7.17.29-AM-1024x767.png" alt="change desktop"></p><p><em>右鍵點擊桌面，然後點修改背景</em></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/Screen-Shot-2015-05-28-at-7.17.52-AM-1024x769.png" alt="Desktop or lock screen"></p><p><em>你會看到這個窗口，這裏你選擇新的桌面背景或鎖屏圖片</em></p><p>進一步，如果你點擊“設置”，你會看到一個菜單展示你所以可以修改的設置。舉個例子，在筆記本電腦上，你可以修改電源設置來控制合上筆記本電腦時的動作。</p><h3 id="_11-安裝-fedy-4-0" tabindex="-1">11) 安裝 Fedy 4.0### <a class="header-anchor" href="#_11-安裝-fedy-4-0" aria-label="Permalink to “11) 安裝 Fedy 4.0###”">​</a></h3><p>Fedy 可以幫助用户和系統管理員來監控系統的運作，並讓他們可以控制系統如其所預期的工作。這裏有一行腳本可以安裝最新版本的 Fedy。打開終端，輸入或粘帖如下行並按下回車。</p><pre><code>su -c &quot;curl https://satya164.github.io/fedy/fedy-installer -o fedy-installer &amp;&amp; chmod +x fedy-installer &amp;&amp; ./fedy-installer&quot;
</code></pre><h3 id="_12-安裝-java" tabindex="-1">12) 安裝 Java### <a class="header-anchor" href="#_12-安裝-java" aria-label="Permalink to “12) 安裝 Java###”">​</a></h3><p>使用如下命令可以很容易的安裝 Java。</p><pre><code>sudo dnf install java -y
</code></pre><p>它會根據你的系統架構自動安裝32位或64位的 Java 發行版。</p><h3 id="_13-在-fedora-22-上安裝瀏覽器" tabindex="-1">13) 在 Fedora 22 上安裝瀏覽器 <a class="header-anchor" href="#_13-在-fedora-22-上安裝瀏覽器" aria-label="Permalink to “13) 在 Fedora 22 上安裝瀏覽器”">​</a></h3><p>Fedora 22的默認瀏覽器是 Firefox，不過其它的瀏覽器也各有優缺點。最終用户選擇瀏覽器會有種種原因。這裏我們提供一些在 Fedora 22上安裝其它瀏覽器的方法。</p><h4 id="安裝-google-chrome" tabindex="-1">安裝 Google Chrome#### <a class="header-anchor" href="#安裝-google-chrome" aria-label="Permalink to “安裝 Google Chrome####”">​</a></h4><p>使用你慣用的編輯器，在 yum 庫目錄中打開或創建 google-chrome.repo 文件。</p><pre><code>sudo gedit /etc/yum.repos.d/google-chrome.repo
</code></pre><p>加入以下內容並保存。</p><pre><code>[google-chrome]
name=google-chrome
baseurl=http://dl.google.com/linux/chrome/rpm/stable/$basearch
enabled=1
gpgcheck=1
gpgkey=https://dl-ssl.google.com/linux/linux_signing_key.pub
</code></pre><p>現在 yum 就配置好可以找到穩定版本的 Chrome 了，使用如下命令安裝它。</p><pre><code>sudo dnf install google-chrome-stable
</code></pre><p>####　安裝 Tor 瀏覽器 ####</p><p>在 Fedora 22 中安裝 Tor 有一點棘手，在 /etc/yum.repos.d 目錄中打開或創建 torproject.repo 文件。</p><pre><code>sudo gedit /etc/yum.repos.d/torproject.repo
</code></pre><p>插入以下內容。</p><pre><code>[tor]
name=Tor repo
enabled=1
baseurl=https://deb.torproject.org/torproject.org/rpm/fc/22/$basearch/
gpgcheck=1
gpgkey=https://deb.torproject.org/torproject.org/rpm/RPM-GPG-KEY-torproject.org.asc

[tor-source]
name=Tor source repo
enabled=1
autorefresh=0
baseurl=https://deb.torproject.org/torproject.org/rpm/fc/22/SRPMS
gpgcheck=1
gpgkey=https://deb.torproject.org/torproject.org/rpm/RPM-GPG-KEY-torproject.org.asc
</code></pre><p>也許會問到 GPG 鍵的指紋，它應該如下。</p><pre><code>3B9E EEB9 7B1E 827B CF0A 0D96 8AF5 653C 5AC0 01F1
</code></pre><p>不幸的是，在 EPEL 和 Fedora 倉庫中有一個相同名字的軟件包，你需要明確排除這個來避免安裝/刪除/修改它。所以，在/etc/yum.repos.d/epel.repo 中加入 <code>Exclude=tor</code> 一行。</p><p>最後，使用如下命令來安裝 Tor。</p><pre><code>sudo dnf install tor
</code></pre><p>安裝完成，啓動服務。</p><pre><code>sudo service tor start
</code></pre><h4 id="安裝-vivaldi" tabindex="-1">安裝 Vivaldi#### <a class="header-anchor" href="#安裝-vivaldi" aria-label="Permalink to “安裝 Vivaldi####”">​</a></h4><p>根據你的系統架構下載32位或64位的 Vivaldi 瀏覽器。</p><pre><code>sudo wget https://vivaldi.com/download/Vivaldi_TP3.1.0.162.9-1.i386.rpm
sudo wget https://vivaldi.com/download/Vivaldi_TP3.1.0.162.9-1.x86_64.rpm
</code></pre><p>使用下列命令安裝下載的 RPM。</p><pre><code>sudo rpm -ivh Vivaldi_TP3.1.0.162.9-1.i386.rpm
sudo rpm -ivh Vivaldi_TP3.1.0.162.9-1.x86_64.rpm
</code></pre><h3 id="尾聲" tabindex="-1">尾聲 <a class="header-anchor" href="#尾聲" aria-label="Permalink to “尾聲”">​</a></h3><p>就是這樣了，一切就緒。使用新系統吧，試試新東西。如果你找不到與你喜好的東西，linux賦予你自由修改它的權利。Fedora自帶有最新的Gnome Shell作為其桌面環境，如果你覺得太臃腫而不喜歡，那麼試試KDE或一些輕量級的DE，像Cinnamon、xfce之類。願你的Fedora之旅十分開心並且沒有困擾！！</p><hr>`,72)),r("p",null,[e[7]||(e[7]=o("via: ",-1)),t(a,{href:"http://linoxide.com/linux-how-to/things-do-after-installing-fedora-22/"},{default:n(()=>[...e[6]||(e[6]=[o("http://linoxide.com/linux-how-to/things-do-after-installing-fedora-22/",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=o("作者：",-1)),t(a,{href:"http://linoxide.com/author/jonathande/"},{default:n(()=>[...e[8]||(e[8]=[o("Jonathan DeMasi",-1)])]),_:1}),e[12]||(e[12]=o(" 譯者：",-1)),t(a,{href:"https://github.com/GOLinux"},{default:n(()=>[...e[9]||(e[9]=[o("GOLinux",-1)])]),_:1}),e[13]||(e[13]=o(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[16]||(e[16]=o("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[14]||(e[14]=[o("LCTT",-1)])]),_:1}),e[17]||(e[17]=o(" 原創翻譯，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...e[15]||(e[15]=[o("Linux中國",-1)])]),_:1}),e[18]||(e[18]=o(" 榮譽推出",-1))])])}const T=d(m,[["render",g]]);export{P as __pageData,T as default};
